using System.Collections;
using System.Linq;
using NUnit.Framework;
using Unity.FPS.AI;
using Unity.FPS.Game;
using Unity.FPS.Gameplay;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace IronRequiem.Tests
{
    public sealed class RobotImpactFeedbackTests
    {
        PlayerCharacterController player;BigBotCombat big;RobotDamageProgression t07;Keyboard keyboard;Mouse mouse;UnityEngine.InputSystem.Utilities.ReadOnlyArray<InputDevice>? previous;float oldCapture;
        [UnitySetUp]public IEnumerator Setup(){Time.timeScale=1;oldCapture=Time.captureDeltaTime;Time.captureDeltaTime=1f/60;previous=InputSystem.actions.devices;keyboard=InputSystem.AddDevice<Keyboard>();mouse=InputSystem.AddDevice<Mouse>();InputSystem.actions.devices=new InputDevice[]{keyboard,mouse};keyboard.MakeCurrent();mouse.MakeCurrent();EditorSceneManager.LoadSceneInPlayMode("Assets/IronRequiem/Scenes/HitWeaponLab.unity",new LoadSceneParameters(LoadSceneMode.Single));yield return null;yield return null;player=Object.FindAnyObjectByType<PlayerCharacterController>();player.GetComponent<Health>().Invincible=true;big=Object.FindAnyObjectByType<BigBotCombat>();t07=Object.FindAnyObjectByType<RobotDamageProgression>();foreach(var enemy in Object.FindObjectsByType<EnemyController>()){enemy.enabled=false;var mobile=enemy.GetComponent<EnemyMobile>();if(mobile)mobile.enabled=false;var combat=enemy.GetComponent<BigBotCombat>();if(combat)combat.enabled=false;var turret=enemy.GetComponent<EnemyTurret>();if(turret)turret.enabled=false;enemy.NavMeshAgent.isStopped=true;}EditorWindow.GetWindow(typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView")).Focus();Cursor.lockState=CursorLockMode.Locked;yield return new WaitForSeconds(.6f);}
        [UnityTearDown]public IEnumerator Cleanup(){Time.captureDeltaTime=oldCapture;Time.timeScale=1;var scene=SceneManager.GetActiveScene();SceneManager.SetActiveScene(SceneManager.CreateScene("HitCleanup"+Time.frameCount));yield return SceneManager.UnloadSceneAsync(scene);InputSystem.actions.devices=previous;InputSystem.RemoveDevice(keyboard);InputSystem.RemoveDevice(mouse);Cursor.lockState=CursorLockMode.None;yield return null;}
        void Move(Vector3 point){var cc=player.GetComponent<CharacterController>();cc.enabled=false;player.transform.SetPositionAndRotation(point,Quaternion.identity);cc.enabled=true;player.CharacterVelocity=Vector3.zero;Physics.SyncTransforms();}
        IEnumerator Tap(Key key){InputSystem.QueueStateEvent(keyboard,new KeyboardState(key));yield return null;yield return null;InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return null;}
        Damageable Body(GameObject go)=>go.GetComponentsInChildren<Damageable>(true).First(d=>d.Health==go.GetComponent<Health>());
        Color Block(Renderer r){var block=new MaterialPropertyBlock();r.GetPropertyBlock(block,0);return block.GetColor("_EmissionColor");}
        [UnityTest]public IEnumerator BulletAndMeleeUnique()
        {
            var hp=big.GetComponent<Health>();var fb=big.GetComponent<RobotHitFeedback>();var box=big.GetComponent<BoxCollider>();for(int i=0;i<4;i++){var extra=big.gameObject.AddComponent<BoxCollider>();extra.center=box.center;extra.size=box.size;}Physics.SyncTransforms();var center=box.bounds.center;Move(new Vector3(center.x,.03f,box.bounds.min.z-5));yield return null;float before=hp.CurrentHealth;int events=0;hp.OnDamaged+=(amount,source)=>events++;InputSystem.QueueStateEvent(mouse,new MouseState{buttons=1});yield return null;yield return null;InputSystem.QueueStateEvent(mouse,new MouseState());float end=Time.time+1;while(hp.CurrentHealth==before&&Time.time<end)yield return null;yield return new WaitForSeconds(.035f);yield return new WaitForEndOfFrame();Assert.That(before-hp.CurrentHealth,Is.EqualTo(5.5f));Assert.That(events,Is.EqualTo(1));Assert.That(fb.ImpactCount,Is.EqualTo(1));Assert.That(fb.Sparks.particleCount,Is.InRange(1,6));Assert.That(fb.IsFlashing,Is.True);var skin=big.GetComponentsInChildren<SkinnedMeshRenderer>().First(r=>r.name=="Torso_LOD0");Assert.That(Block(skin).maxColorComponent,Is.GreaterThan(.1f));Assert.That(t07.GetComponent<RobotHitFeedback>().ImpactCount,Is.Zero);ScreenCapture.CaptureScreenshot("Tools/IronRequiem/Reports/HitWeaponV04/bullet-white-flash.png");
            yield return new WaitForSeconds(.4f);Move(new Vector3(center.x,.03f,box.bounds.min.z-.45f));before=hp.CurrentHealth;int impacts=fb.ImpactCount;yield return Tap(Key.F);yield return new WaitForSeconds(.65f);Assert.That(before-hp.CurrentHealth,Is.EqualTo(25));Assert.That(fb.ImpactCount-impacts,Is.EqualTo(1));Assert.That(player.GetComponent<ProtagonistMelee>().LastHitCount,Is.EqualTo(1));Assert.That(fb.IsFlashing,Is.False);Assert.That(Block(skin).maxColorComponent,Is.Zero);
        }
        [UnityTest]public IEnumerator RestoreStageAndRepeatedHits()
        {
            var fb=t07.GetComponent<RobotHitFeedback>();var body=Body(t07.gameObject);var r=t07.GetComponentsInChildren<SkinnedMeshRenderer>().First(v=>v.name=="Body_LOD0");var other=big.GetComponentsInChildren<SkinnedMeshRenderer>().First(v=>v.name=="Torso_LOD0");var otherMaterial=other.sharedMaterial;var otherColor=otherMaterial.GetColor("_BaseColor");var point=r.bounds.center;var root=t07.transform.position;body.InflictDamageAtPoint(41,false,player.gameObject,point,Vector3.back);var stage=r.sharedMaterial;var stageColor=stage.GetColor("_BaseColor");yield return new WaitForSeconds(.035f);yield return new WaitForEndOfFrame();Assert.That(Block(r).maxColorComponent,Is.GreaterThan(.1f));Assert.That(Block(other).maxColorComponent,Is.Zero);Assert.That(big.GetComponent<RobotHitFeedback>().IsFlashing,Is.False);
            for(int i=0;i<20;i++){body.InflictDamageAtPoint(1,false,player.gameObject,point,Vector3.back);yield return new WaitForSeconds(.03f);}yield return new WaitForSeconds(.4f);Assert.That(t07.Stage,Is.EqualTo(1));Assert.That(r.sharedMaterial,Is.SameAs(stage));Assert.That(stage.GetColor("_BaseColor"),Is.EqualTo(stageColor));Assert.That(other.sharedMaterial,Is.SameAs(otherMaterial));Assert.That(otherMaterial.GetColor("_BaseColor"),Is.EqualTo(otherColor));Assert.That(Block(r).maxColorComponent,Is.Zero);Assert.That(fb.FlashCount,Is.LessThan(10));Assert.That(fb.ReactionCount,Is.LessThanOrEqualTo(4));Assert.That(fb.ImpactCount,Is.EqualTo(21));Assert.That(Vector3.Distance(t07.transform.position,root),Is.LessThan(.001f));Assert.That(fb.Sparks.particleCount,Is.Zero);
        }
        [UnityTest]public IEnumerator AttacksContinueAndDeathClears()
        {
            var enemy=big.GetComponent<EnemyController>();var hp=big.GetComponent<Health>();var fb=big.GetComponent<RobotHitFeedback>();enemy.PatrolPath=null;enemy.NavMeshAgent.Warp(new Vector3(-10,0,12));big.transform.rotation=Quaternion.Euler(0,180,0);Move(new Vector3(-10,.03f,5));enemy.enabled=true;big.enabled=true;big.GetComponent<EnemyMobile>().enabled=true;enemy.NavMeshAgent.isStopped=true;var origin=big.transform.position;int shots=big.ShotsFired;var damage=Body(big.gameObject);float end=Time.time+8,next=0;while(Time.time<end){if(Time.time>=next){damage.InflictDamageAtPoint(1,false,player.gameObject,big.transform.position+Vector3.up*1.6f,Vector3.back);next=Time.time+.1f;}yield return null;}Assert.That(big.ShotsFired,Is.GreaterThan(shots),"Damage presentation must not cancel repeated attacks");Assert.That(fb.ReactionCount,Is.LessThan(30));Assert.That(Vector3.Distance(big.transform.position,origin),Is.LessThan(.06f));shots=big.ShotsFired;hp.TakeDamage(hp.MaxHealth+1,player.gameObject);yield return null;Assert.That(fb.IsFlashing,Is.False);Assert.That(fb.Sparks.isPlaying,Is.False);yield return new WaitForSeconds(1);Assert.That(big.ShotsFired,Is.EqualTo(shots));Assert.That(big.GetComponent<BigBotDestruction>().DeathCount,Is.EqualTo(1));
        }
        [UnityTest]public IEnumerator ModuleSwap()
        {
            Move(new Vector3(-9,.03f,-4));t07.GetComponentInChildren<DetachableCannon>().Detach();var module=Object.FindObjectsByType<StolenCannon>().Single(m=>m.State==StolenCannonState.Available);module.Body.isKinematic=true;Physics.SyncTransforms();var target=player.PlayerCamera.transform.position+player.PlayerCamera.transform.forward*1.3f;module.transform.position+=target-module.SolidCollider.bounds.center;Physics.SyncTransforms();yield return new WaitForSeconds(.4f);yield return Tap(Key.E);yield return new WaitForSeconds(2.1f);var hands=player.GetComponent<ProtagonistHandsPresentation>();var manager=player.GetComponent<PlayerWeaponsManager>();Assert.That(hands.CurrentRepresentation,Is.EqualTo(ProtagonistHandsPresentation.Representation.StolenCannon));float energy=module.Ammo.Remaining;yield return Tap(Key.Digit1);yield return new WaitForSeconds(2.1f);Assert.That(manager.GetActiveWeapon().SourcePrefab.name,Is.EqualTo("Weapon_IR_Integrated_v04"));Assert.That(hands.RightHandVisible,Is.False);yield return Tap(Key.Digit2);yield return new WaitForSeconds(2.1f);Assert.That(module.Ammo.Remaining,Is.EqualTo(energy));Assert.That(hands.CurrentRepresentation,Is.EqualTo(ProtagonistHandsPresentation.Representation.StolenCannon));
        }
    }
}